SELECT 137 AS trade_id, MIN(low_price) AS lo30, MAX(high_price) AS hi30, COUNT(*) AS n, SUM(number_of_trades=0) AS zero_trade FROM crypto_ai.candle WHERE interval_code='1m' AND closed=1 AND symbol='EGLDUSDT' AND open_time BETWEEN FROM_UNIXTIME(1791739500) AND FROM_UNIXTIME(1791741240)
